"""Tests for Bio.Align.tabular module."""
import os
import unittest
import pytest
from tempfile import NamedTemporaryFile

from Bio import Align
from Bio.Align import substitution_matrices
from Bio import SeqIO
from Bio.Seq import Seq

np = pytest.importorskip("numpy")
substitution_matrix = substitution_matrices.load("BLOSUM62")


class TestFastaProtein(unittest.TestCase):
    query = Seq(
        "MPMILGYWNVRGLTHPIRMLLEYTDSSYDEKRYTMGDAPDFDRSQWLNEKFKLGLDFPNLPYLIDGSHKITQSNAILRYLARKHHLDGETEEERIRADIVENQVMDTRMQLIMLCYNPDFEKQKPEFLKTIPEKMKLYSEFLGKRPWFAGDKVTYVDFLAYDILDQYRMFEPKCLDAFPNLRDFLARFEGLKKISAYMKSSRYIATPIFSKMAHWSNK"
    )

    filename = os.path.join("Fasta", "protein_lib.fa")
    records = SeqIO.parse(filename, "fasta")
    targets = {record.id: record.seq.upper() for record in records}

    def test_m8CB(self):
        # Alignment file obtained by running
        # fasta36 -q -m 8CB seq/mgstm1.aa seq/prot_test.lseg
        # in the fasta36 source distribution
        path = "Fasta/protein_m8CB.txt"
        alignments = Align.parse(path, "tabular")
        self.check_m8CB(alignments)
        alignments = iter(alignments)
        self.check_m8CB(alignments)
        with Align.parse(path, "tabular") as alignments:
            self.check_m8CB(alignments)
        with pytest.raises(AttributeError):
            alignments._stream
        with Align.parse(path, "tabular") as alignments:
            pass
        with pytest.raises(AttributeError):
            alignments._stream
        with open(path) as stream:
            data = stream.read()
        stream = NamedTemporaryFile("w+t")
        stream.write(data)
        stream.seek(0)
        alignments = Align.parse(stream, "tabular")
        self.check_m8CB(alignments)

    def check_m8CB(self, alignments):
        assert alignments.metadata["Command line"] == "fasta36 -q -m 8CB seq/mgstm1.aa seq/prot_test.lseg"
        assert alignments.metadata["Program"] == "FASTA"
        assert alignments.metadata["Version"] == "36.3.8h May, 2020"
        assert alignments.metadata["Database"] == "seq/prot_test.lseg"
        # sp|P10649|GSTM1_MOUSE   sp|P09488|GSTM1_HUMAN
        alignment = next(alignments)
        assert len(alignment) == 2
        assert alignment.annotations["% identity"] == pytest.approx(77.98, abs=5e-8)
        assert alignment.annotations["gap opens"] == 0
        aligned = alignment.aligned
        assert sum(end - start for start, end in aligned[0]) == 218
        assert sum(end - start for start, end in aligned[1]) == 218
        assert alignment.shape == (2, 218 + 0)
        assert alignment.sequences[0].id == "sp|P09488|GSTM1_HUMAN"
        assert alignment.sequences[1].id == "sp|P10649|GSTM1_MOUSE"
        assert alignment.annotations["mismatches"] == 48
        assert alignment.annotations["evalue"] == pytest.approx(6.1e-78, abs=5e-80)
        assert alignment.annotations["bit score"] == pytest.approx(275.6, abs=5e-8)
        assert str(alignment) == """\
sp|P09488         0 ????????????????????????????????????????????????????????????
                  0 ||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||
sp|P10649         0 ????????????????????????????????????????????????????????????

sp|P09488        60 ????????????????????????????????????????????????????????????
                 60 ||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||
sp|P10649        60 ????????????????????????????????????????????????????????????

sp|P09488       120 ????????????????????????????????????????????????????????????
                120 ||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||
sp|P10649       120 ????????????????????????????????????????????????????????????

sp|P09488       180 ?????????????????????????????????????? 218
                180 |||||||||||||||||||||||||||||||||||||| 218
sp|P10649       180 ?????????????????????????????????????? 218
"""
        assert np.array_equal(
                alignment.coordinates,
                np.array([[0, 218], [0, 218]]),
            )
        query = self.query
        target = self.targets[alignment.sequences[0].id]
        assert len(alignment.sequences[0].seq) == 218
        assert len(alignment.sequences[1].seq) == len(query)
        alignment.sequences[0].seq = target
        alignment.sequences[1].seq = query
