        # Alignment file obtained by running
        # fasta36 -q -m 8CB seq/mgstm1.aa seq/prot_test.lseg
        # in the fasta36 source distribution
        path = "Fasta/protein_m8CC.txt"
        alignments = Align.parse(path, "tabular")
        assert alignments.metadata["Command line"] == "fasta36 -q -m 8CC seq/mgstm1.aa seq/prot_test.lseg"
        assert alignments.metadata["Program"] == "FASTA"
        assert alignments.metadata["Version"] == "36.3.8h May, 2020"
