    def test_m8CC(self):
        # Alignment file obtained by running
        # fasta36 -m 8CC seq/mgstm1.nt seq/gst.nlib
        # in the fasta36 source distribution
        path = "Fasta/nucleotide_m8CC.txt"
        alignments = Align.parse(path, "tabular")
        assert alignments.metadata["Command line"] == "fasta36 -m 8CC seq/mgstm1.nt seq/gst.nlib"
        assert alignments.metadata["Program"] == "FASTA"
        assert alignments.metadata["Version"] == "36.3.8h May, 2020"
        assert alignments.metadata["Database"] == "seq/gst.nlib"
        # pGT875   pGT875
